def clue(p, a, c, h, e, es, fig=None):
    d = {'prompt': p, 'answer': a, 'code': c, 'hint': h, 'explain': e, 'es': {'prompt': es[0], 'hint': es[1], 'explain': es[2]}}
    if fig: d['figure'] = fig[0]; d['es']['figure'] = fig[1]
